insert into public.personas (code, name, handle, color, description, keywords, ng_words, tone, threshold, active) values
  ('P01', 'テック × 投資 × 情報収集', 'tech-invest', '#6f95d6', 'AI・半導体・資金調達の動きを、投資判断の材料として追う会社員。', array['AI', '半導体', '資金調達', '決算'], array['芸能'], '簡潔・データ重視', 75, true),
  ('P02', '筋トレ × 節約 × 自炊', 'fit-saving', '#5cc489', 'お金をかけずに体づくりをしたい20代。自宅トレと安い高タンパク食に関心。', array['筋トレ', '自炊', '節約', 'タンパク質'], array['芸能', 'サプリ広告'], '前向き・実践的', 70, true),
  ('P03', '子育て × 共働き × 時短', 'family-time', '#9d84dc', '共働きで未就学児を育てる30代。制度変更と時短の工夫を求める。', array['保育', '育休', '時短', '家事分担'], array['芸能', '炎上'], 'やさしく実用的', 70, true),
  ('P04', '仕事 × 孤独 × 日常改善', 'solo-life', '#e9ad62', '一人暮らしの会社員。仕事後の時間と家計、ひとりの過ごし方を少しずつ良くしたい。', array['一人暮らし', '節約', '習慣', '時間術'], array['芸能'], '静かで寄り添う', 80, true),
  ('P05', '地方 × 移住 × リモート', 'local-remote', '#dc6d88', 'リモートワークで地方移住を検討・実践している人。', array['移住', '地方創生', 'リモートワーク', '補助金'], array['芸能'], 'フラット・体験重視', 70, true)
insert into public.articles (type, kind, source_name, category, title, excerpt, url, collected_at, status, primary_persona_id, verdict, editor_comment, notion_db, published_at) values
  ('news', 'NEWS', 'サンプル生活新聞', 'ライフ', '業務スーパーで揃う高タンパク食材ベスト10', '100gあたりの価格とタンパク質量で比較したランキング。', 'https://example.com/article/sample-1', now() - interval '1091 minutes', 'approved', (select id from public.personas where code = 'P02'), 'adopt', '', 'articles', null),
