  ('sns', 'THREADS', '@mama_engineer', '子育て', '時短勤務でも回る、共働き家庭の1日のスケジュール', '朝5時起きのルーティンと、夫婦の家事分担表を公開します。', 'https://example.com/article/sample-8', now() - interval '510 minutes', 'approved', (select id from public.personas where code = 'P03'), 'adopt', '', 'sns_posts', null),
  ('news', 'NEWS', 'サンプル社会新聞', '子育て', '「こども誰でも通園制度」来年度から本格実施へ', '就労要件を問わず保育所を利用できる制度が全国で本格実施。月の利用上限時間も見直される見通し。', 'https://example.com/article/sample-9', now() - interval '427 minutes', 'published', (select id from public.personas where code = 'P03'), 'adopt', '保育制度の変更という点で、いま読む価値のある記事です。', 'articles', now()),
  ('sns', 'X', '@semicon_watch', 'テック', 'TSMC熊本第2工場、稼働前倒しの観測', '関係者筋によると第2工場の稼働時期が前倒しになる可能性。周辺自治体では住宅需要も高まっている。', 'https://example.com/article/sample-10', now() - interval '344 minutes', 'pending', (select id from public.personas where code = 'P01'), 'adopt', '', 'sns_posts', null),
  ('news', 'NEWS', 'テック経済ニュース', 'テック', '国内AIスタートアップ、シリーズBで80億円調達', '生成AI向け推論チップを手がける国内スタートアップが資金調達を発表。2027年の量産開始を目指す。', 'https://example.com/article/sample-11', now() - interval '261 minutes', 'published', (select id from public.personas where code = 'P01'), 'adopt', '資金調達の一次情報という点で、いま読む価値のある記事です。', 'articles', now()),
  ('sns', 'NOTE', 'sample_saving', 'マネー', '手取り20万円台の一人暮らし、固定費を月1.5万円減らした記録', '通信費・サブスク・電気代の見直しで、無理なく固定費を削った手順を公開。', 'https://example.com/article/sample-12', now() - interval '178 minutes', 'approved', (select id from public.personas where code = 'P04'), 'adopt', '', 'sns_posts', null),
  ('sns', 'YOUTUBE', 'サンプル暮らしCH', 'ライフ', '仕事帰りの90分を有効活用する方法', '帰宅後のだらだら時間を減らすための、着替え・夕食・入浴の順番の工夫。', 'https://example.com/article/sample-13', now() - interval '95 minutes', 'published', (select id from public.personas where code = 'P04'), 'adopt', '仕事後の時間術という点で、いま読む価値のある記事です。', 'sns_posts', now()),
  ('news', 'NEWS', 'サンプル生活新聞', 'ライフ', '月1万円以内で始める筋トレ食生活', '鶏むね肉・卵・豆腐を軸に、1食300円以内で必要なタンパク質を確保する献立例を紹介。', 'https://example.com/article/sample-14', now() - interval '12 minutes', 'approved', (select id from public.personas where code = 'P02'), 'adopt', '', 'articles', null)
